id.txt@all<js>
(function(){
  try{
    var MAP = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    function d64(x){
      var t = String(x).replace(/[^A-Za-z0-9+\/]/g, '');
      var buf = 0, bits = 0, bs = [], i, v;
      for(i = 0; i < t.length; i++){
        v = MAP.indexOf(t.charAt(i));
        if(v < 0){ continue; }
        buf = (buf << 6) | v;
        bits += 6;
        if(bits >= 8){ bits -= 8; bs.push((buf >> bits) & 0xFF); }
      }
      var r = '', k = 0, b0, b1, b2, b3, cp;
      while(k < bs.length){
        b0 = bs[k++];
        if(b0 < 0x80){ r += String.fromCharCode(b0); }
        else if(b0 < 0xE0){ b1 = bs[k++]; r += String.fromCharCode(((b0 & 0x1F) << 6) | (b1 & 0x3F)); }
        else if(b0 < 0xF0){ b1 = bs[k++]; b2 = bs[k++]; r += String.fromCharCode(((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F)); }
        else { b1 = bs[k++]; b2 = bs[k++]; b3 = bs[k++]; cp = ((b0 & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F); cp -= 0x10000; r += String.fromCharCode(0xD800 + (cp >> 10), 0xDC00 + (cp & 0x3FF)); }
      }
      return r;
    }
    function blobs(h){
      var re = /writeln\([^'"]*['"]([A-Za-z0-9+\/=]+)['"]/g, m, o = '';
      while((m = re.exec(h)) !== null){ o += d64(m[1]); }
      return o;
    }
    var bu = String(baseUrl || '');
    var origin = (bu.match(/^https?:\/\/[^\/]+/) || [''])[0] || 'https://m.baicaolu.com';
    function abs(u){ return /^https?:/i.test(u) ? u : origin + (u.charAt(0) === '/' ? '' : '/') + u; }
    var url = bu.split('#')[0];
    var texts = [], g = 0, seen = {};
    while(url && g < 8){
      g++;
      if(seen[url]){ break; }
      seen[url] = 1;
      var html;
      if(g === 1){
        html = String(result);
        if(html.indexOf('hhekgsv') < 0){
          try { html = String(java.connect(url).body()); } catch(e){ html = String(result); }
        }
      } else {
        try { html = String(java.connect(url).body()); } catch(e){ html = ''; }
      }
      if(!html){ break; }
      var t = blobs(html);
      if(t){ texts.push(t); }
      var m = html.match(/hhekgsv\s*=\s*['"]([^'"]+)['"]/);
      if(!m){ break; }
      var nx = m[1];
      if(!/_\d+\.html(\?|#|$)/.test(nx)){ break; }
      var nurl = abs(nx);
      if(nurl === url){ break; }
      url = nurl;
    }
    var raw = texts.join('\n');
    if(raw.replace(/\s+/g, '') === ''){
      if(String(result).indexOf('内容正在更新') > -1){ return '本章站点暂无正文：页面提示「内容正在更新，请稍后查看」（非书源问题）'; }
      return '诊断[页数=' + texts.length + ',无base64块,url=' + bu + ']';
    }
    var out = raw.replace(/<p[^>]*>/g, '\n').replace(/<\/p>/g, '\n').replace(/<br\s*\/?>/g, '\n').replace(/<[^>]+>/g, '');
    var lines = out.split('\n'), keep = [], j, tt;
    for(j = 0; j < lines.length; j++){
      tt = lines[j].replace(/\s+/g, '');
      if(tt === ''){ continue; }
      if(tt.indexOf('请退出浏览器阅读模式') >= 0){ continue; }
      var t2 = lines[j].trim();
      if(keep.length > 0 && keep[keep.length-1] === t2){ continue; }
      keep.push(t2);
    }
    if(keep.length === 0){ return '本章站点暂无正文'; }
    return keep.join('\n');
  }catch(e){
    return '正文解析异常: ' + e;
  }
})()
</js>
